export const investigations = Object.fromEntries(text.trim().split('\n').map(line => {
  const [id, scene, action, shortcut, evidence] = line.split('¦');
  if (!id || !scene || !action || !shortcut || !evidence) throw Error('Incomplete late-world investigation: '+id);
  return [Number(id), {scene, action, shortcut, evidence}];
}));
